				t.Fatalf("KeyspaceMetadata failed: %v", err)
			}
			if _, ok := km.Indexes[idxName]; !ok {
				t.Errorf("expected index %q in keyspace metadata indexes", idxName)
			}
		})

		t.Run("with_materialized_view", func(t *testing.T) {
