func TestRoutingKeyCacheUsesOverriddenKeyspace(t *testing.T) {
	session := createV2Session(t)
	defer session.Close()
	if session.cfg.ProtoVersion < 5 {
		t.Skip("This tests only runs on proto > 4 due SetKeyspace availability")
	}
	ks := testKeyspaceName(t)
	table := testTableName(t)
	cassandraDDL(t, session, fmt.Sprintf("CREATE KEYSPACE %s WITH replication={'class':'SimpleStrategy','replication_factor':1}", ks))
	defer cassandraDDL(t, session, "DROP KEYSPACE "+ks)
	for _, keyspace := range []string{fixtureKeyspace(""), ks} {
		cassandraDDL(t, session, fmt.Sprintf("CREATE TABLE %s.%s(id int PRIMARY KEY)", keyspace, table))
	}
	defer cassandraDDL(t, session, ("DROP TABLE "+fixtureKeyspace("")+".")+table)
	insert := "INSERT INTO " + table + "(id) VALUES(?)"
	selectCQL := "SELECT * FROM " + table + " WHERE id=?"
	for i, keyspace := range []string{fixtureKeyspace(""), ks} {
		write := cassandraWriteBound(t, session, insert, []Value{IntValue(int32(i + 1))}, PrepareOptions{Keyspace: keyspace})
		require.Equal(t, keyspace, write.Routing().Keyspace)
		require.True(t, write.Routing().Token.Set)
		item := cassandraItem(t, write)
		require.Equal(t, keyspace, item.request.routing.Keyspace)
		runtime := session.typedRuntime()
		runtime.mu.Lock()
		found := false
		for key, state := range runtime.prepared {
			if key.cql == insert && key.keyspace == keyspace {
				found = true
				require.Equal(t, keyspace, state.info.Keyspace)
			}
		}
		runtime.mu.Unlock()
		require.True(t, found, "cache must include keyspace-specific binding")
		read := cassandraDynamicBound(t, session, selectCQL, []Value{IntValue(1)}, PrepareOptions{Keyspace: keyspace})
		require.Equal(t, keyspace, read.Routing().Keyspace)
		require.True(t, read.Routing().Token.Set)
	}
}

func TestGetHostPortMapping(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	session := createV2Session(t)
	defer session.Close()
	keyspace := fixtureKeyspace("")

	table := testTableName(t)
	qualifiedTable := keyspace + "." + table

	if err := v2CreateTable(ctx, session, fmt.Sprintf(`CREATE TABLE %s.%s (
    connection_id uuid,
    host_id uuid,
    Address text,
    port int,
    tls_port int,
    alternator_port int,
    alternator_https_port int,
    Datacenter text,
    Rack text,
    PRIMARY KEY (connection_id, host_id))`, keyspace, table)); err != nil {
		t.Fatal(err)
	}

	var hostIDs []string
	for i := 0; i < 3; i++ {
		hostIDs = append(hostIDs, MustRandomUUID().String())
	}
	var connectionIDs []string
	for i := 0; i < 3; i++ {
		connectionIDs = append(connectionIDs, MustRandomUUID().String())
	}

	// These rows are read back below through session.control, and controlConn.query
	// pins every query it issues to Consistency(One). The session default is Quorum,
	// which acks once 2 of the 3 replicas have the row -- so a ONE read can be served
	// by the third replica before it has been written, and rows go missing. Write the
	// fixture at All so the read cannot outrun replication.
	racks := []string{"rack1", "rack2", "rack3"}
	var expected []clientRoute
	var expectedTLS []clientRoute
	for id, hostID := range hostIDs {
		rack := racks[id]
		ip := net.ParseIP(fmt.Sprintf("127.0.0.%d", id+1))
		for _, connectionID := range connectionIDs {
			prepared, err := Prepare(ctx, session, Statement[[]Value, Unit]{
				CQL: fmt.Sprintf(`INSERT INTO %s (
                    connection_id, host_id, Address, port, tls_port, alternator_port, alternator_https_port, Datacenter, Rack)
                    VALUES (?, ?, ?, 9042, 9142, 0, 0, 'dc1', ?)`, qualifiedTable),
				Kind: OrdinaryStatement, Params: DynamicParams, Rows: NoRows,
			}, PrepareOptions{})
			if err != nil {
				t.Fatal(err)
			}
			bound, err := BindOwned(prepared, []Value{UUIDValue(codecTestMust(ParseUUID(connectionID))), UUIDValue(codecTestMust(ParseUUID(hostID))), codecTestMust(TextValue(ip.String())), codecTestMust(TextValue(rack))})
			if err != nil {
				t.Fatal(err)
			}
			_, err = Exec(ctx, session, bound, Options{Consistency: Option[Consistency]{Set: true, Value: All}})
			bound.Close()
			if waitErr := bound.Wait(ctx); waitErr != nil {
				t.Fatal(waitErr)
			}

			if err != nil {
				t.Fatalf("unable to insert connection metadata: %s", err.Error())
			}
			expected = append(expected, clientRoute{
				connectionID: connectionID,
				hostID:       hostID,
				address:      ip.String(),
				port:         9042,
			})
			expectedTLS = append(expectedTLS, clientRoute{
				connectionID: connectionID,
				hostID:       hostID,
				address:      ip.String(),
				port:         9142,
			})
		}
	}

	sortClientRoutes(expected)
	sortClientRoutes(expectedTLS)
	expectedFirstHost := filterClientRoutesByHostID(expected, hostIDs[0])

	tcases := []struct {
		name     string
		method   func(controlConnection) ([]clientRoute, error)
		expected []clientRoute
	}{
		{
			name: "get-for-connection-ids",
			method: func(controlConnection) ([]clientRoute, error) {
				return getHostPortMappingForConnectionIDs(session.control, qualifiedTable, connectionIDs, false)
			},
			expected: expected,
		},
		{
			name: "get-for-pairs",
			method: func(controlConnection) ([]clientRoute, error) {
				return getHostPortMappingForPairs(session.control, qualifiedTable, makeClientRoutePairs(connectionIDs, hostIDs), false)
			},
			expected: expected,
		},
		{
			name: "get-for-single-host-pairs",
			method: func(controlConnection) ([]clientRoute, error) {
				return getHostPortMappingForPairs(session.control, qualifiedTable, makeClientRoutePairs(connectionIDs, hostIDs[:1]), false)
			},
			expected: expectedFirstHost,
		},
		{
			name: "get-for-connection-ids-tls",
			method: func(controlConnection) ([]clientRoute, error) {
				return getHostPortMappingForConnectionIDs(session.control, qualifiedTable, connectionIDs, true)
			},
			expected: expectedTLS,
		},
	}

	for _, tc := range tcases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := tc.method(session.control)
			if err != nil {
				t.Fatal(err)
			}

			sortClientRoutes(got)

			if diff := cmp.Diff(got, tc.expected, cmp.AllowUnexported(clientRoute{})); diff != "" {
				t.Errorf("got unexpected result: %s", diff)
			}
		})
	}
}

func TestCloudConnection(t *testing.T) {
	t.Parallel()

	if !*gocql.FlagRunSslTest {
		t.Skip("Skipping because SSL is not enabled on cluster")
	}

	if *gocql.FlagDistribution != "scylla" {
		t.Skip("Skipping because it is designed for scylla, but running on something else")
	}

	const (
		sslPort        = 9142
		datacenterName = "datacenter1"
	)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	hosts := map[string]string{}

	cluster := gocql.CreateV2Cluster(func(config *gocql.Config) {
		config.Port = sslPort
	})
	session, err := gocql.Connect(ctx, cluster)
	if err != nil {
		t.Fatal(err)
	}

	defer session.Close()
	rows, err := cloudHostRows(ctx, session, "SELECT broadcast_address, host_id FROM system.local WHERE key='local'", gocql.Options{})
	if err != nil {
		t.Fatal(err)
	}
	if !rows.Next() {
		t.Fatalf("read local host: %v", rows.Err())
	}
	local := rows.Row()
	localAddress, localHostID := local.First.String(), local.Second
	hosts[localHostID.String()] = net.JoinHostPort(localAddress, fmt.Sprintf("%d", sslPort))
	if err := rows.Close(); err != nil {
		t.Fatal(err)
	}

	// Both system tables must describe the same coordinator's view of the ring.
	rows, err = cloudHostRows(ctx, session, "SELECT peer, host_id FROM system.peers", gocql.Options{
		HostID: gocql.Option[gocql.UUID]{Value: localHostID, Set: true},
	})
	if err != nil {
		t.Fatal(err)
	}
	for rows.Next() {
		peer := rows.Row()
		hosts[peer.Second.String()] = net.JoinHostPort(peer.First.String(), fmt.Sprintf("%d", sslPort))
	}
	if err := rows.Close(); err != nil {
		t.Fatal(err)
	}

	session.Close()

	logger := gocql.NewTestLogger()
	defer func() {
		if t.Failed() {
			os.Stdout.WriteString(logger.String())
		}
	}()

	proxy := &sniProxy{
		hosts:          hosts,
		defaultBackend: net.JoinHostPort(localAddress, fmt.Sprintf("%d", sslPort)),
		logger:         logger,
	}

	proxyAddress, err := proxy.Run(ctx)
	if err != nil {
		t.Fatal(err)
	}
	defer proxy.Close()

	cc := &scyllacloud.ConnectionConfig{
		Datacenters: map[string]*scyllacloud.Datacenter{
			datacenterName: {
				CertificateAuthorityPath: "testdata/pki/ca.crt",
				Server:                   proxyAddress,
				TLSServerName:            "any",
				NodeDomain:               "cloud.scylladb.com",
				InsecureSkipTLSVerify:    true,
			},
		},
		AuthInfos: map[string]*scyllacloud.AuthInfo{
			"ai-1": {
				Username:              "cassandra",
				Password:              "cassandra",
				ClientKeyPath:         "testdata/pki/gocql.key",
				ClientCertificatePath: "testdata/pki/gocql.crt",
			},
		},
		Contexts: map[string]*scyllacloud.Context{
			"default-context": {
				AuthInfoName:   "ai-1",
				DatacenterName: datacenterName,
			},
		},
		CurrentContext: "default-context",
	}

	configPath, err := writeYamlToTempFile(cc)
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(configPath)

	fixtureTLS := cluster.TLS
	cluster, err = scyllacloud.NewCloudCluster(configPath, func(config *gocql.Config) {
		// Forward connections directed to node domain to our test SNI proxy.
		config.Dialer = gocql.DialerFunc(func(ctx context.Context, target gocql.DialTarget) (net.Conn, error) {
			network, addr := target.Network, target.Address
			if strings.Contains(addr, cc.Datacenters[datacenterName].NodeDomain) {
				addr = cc.Datacenters[datacenterName].Server
			}
			return (&net.Dialer{}).DialContext(ctx, network, addr)
		})
	})
	if err != nil {
		t.Fatal(err)
	}
	// The test backend identifies itself by URI SAN. Preserve UUID-based SNI
	// and client authentication while validating its CA and fixture URI.
	cloudTLS := cluster.TLSForHost
	cluster.TLSForHost = func(ctx context.Context, host gocql.HostSnapshot) (*tls.Config, error) {
		config, err := cloudTLS(ctx, host)
		if err != nil {
			return nil, err
		}
		config.InsecureSkipVerify = true
		config.VerifyConnection = fixtureTLS.VerifyConnection
		return config, nil
	}
	session, err = gocql.Connect(ctx, cluster)
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()

	if err := gocql.WaitUntilPoolsStopFilling(ctx, session, 10*time.Second); err != nil {
		t.Fatal(err)
	}

	ringHosts := session.Metadata().Hosts()
	if len(ringHosts) != len(hosts) {
		t.Errorf("expected %d hosts in ring, got %d", len(hosts), len(ringHosts))
	}

	for _, host := range ringHosts {
		rows, err := cloudHostRows(ctx, session, "SELECT broadcast_address, host_id FROM system.local WHERE key='local'", gocql.Options{
			HostID: gocql.Option[gocql.UUID]{Value: host.ID, Set: true},
		})
		if err != nil {
			t.Fatal(err)
		}
		if !rows.Next() {
			t.Fatalf("read cloud host %s: %v", host.ID, rows.Err())
		}
		if actual := rows.Row().Second; actual != host.ID {
			t.Errorf("SNI route for %s reached host %s", host.ID, actual)
		}
		if err := rows.Close(); err != nil {
			t.Fatal(err)
		}
	}

	snisCount := map[string]int{}
	events := proxy.GetEvents()
	for _, event := range events {
		snisCount[event]++
	}

	for hostID := range hosts {
		sni := fmt.Sprintf("%s.%s", hostID, cc.Datacenters[datacenterName].NodeDomain)
		count, ok := snisCount[sni]
		if !ok {
			t.Errorf("not found connection to host %q", hostID)
		}
		if count != cluster.Pool.ConnectionsPerHost {
			t.Errorf("expected %d connections to host %q, got %d", cluster.Pool.ConnectionsPerHost, sni, count)
		}
	}
}

