func TestDNS(t *testing.T) {
	t.Parallel()

	checkIfSessionWorking := func(t *testing.T, cluster Config, hosts []string) {
		s, err := Connect(context.Background(), cluster)
		if err != nil {
			t.Fatalf("failed to create session: %v", err)
		}
		defer s.Close()

		err = s.RefreshMetadata(context.Background())
		if err != nil {
			t.Fatalf("failed to refresh ring: %v", err)
		}

		rows, err := v2Query(context.Background(), s, "select * from system.peers")
		if err == nil {
			for rows.Next() {
			}
			err = rows.Err()
			rows.Close()
		}
		if err != nil {
			t.Fatalf("failed to execute query: %v", err)
		}
		ringHosts := s.Metadata().Hosts()
		if len(ringHosts) != len(hosts) {
			t.Fatalf("wrong number of hosts: got %d, want %d", len(ringHosts), len(hosts))
		}
	}

	OneDNSPerNode := func(c *Config) {
		r := newMockDNSResolver()
		var dnsRecords []string
		for id, host := range c.ContactPoints {
			dns := fmt.Sprintf("node%d.cluster.local", id+1)
			dnsRecords = append(dnsRecords, dns)
			r.Update(dns, MustIP(host))
		}
		c.DNSResolver = r
		c.ContactPoints = dnsRecords
	}

	OneDNSPerCluster := func(c *Config) {
		r := newMockDNSResolver()
		var hostIPs []net.IP
		for _, host := range c.ContactPoints {
			hostIPs = append(hostIPs, MustIP(host))
		}
		r.Update("cluster.local", hostIPs...)
		c.DNSResolver = r
		c.ContactPoints = []string{"cluster.local"}
	}

	OneDNSPerClusterFirstBroken := func(c *Config) {
		r := newMockDNSResolver()
		var hostIPs []net.IP
		for _, host := range c.ContactPoints {
			hostIPs = append(hostIPs, MustIP(host))
		}
		hostIPs[0] = MustIP("0.0.0.0")
		r.Update("cluster.local", hostIPs...)
		c.DNSResolver = r
		c.ContactPoints = []string{"cluster.local"}
	}

	WithAddressTranslator := func(c *Config) {
		var toAddresses []net.IP
		var fromAddresses []net.IP
		var clusterHosts []string
		for _, host := range c.ContactPoints {
			ip := MustIP(host)

			var fromAddress net.IP
			if ip.To4().String() == ip.String() {
				ip = ip.To4()
				fromAddress = net.IPv4(ip[0], ip[1], ip[2]+1, ip[3])
			} else {
				fromAddress = net.IP{ip[0], ip[1], ip[2], ip[3], ip[4], ip[5], ip[6], ip[7], ip[8], ip[9], ip[10], ip[11], ip[12] + 1, ip[13], ip[14], ip[15]}
			}
			toAddresses = append(toAddresses, ip)
			fromAddresses = append(fromAddresses, fromAddress)
			clusterHosts = append(clusterHosts, fromAddress.String())
		}

		c.AddressTranslator = AddressTranslatorFunc(func(addr net.IP, port int) (net.IP, int) {
			for id, host := range fromAddresses {
				if host.Equal(addr) {
					return toAddresses[id], port
				}
			}
			for _, host := range toAddresses {
				if host.Equal(addr) {
					return addr, port
				}
			}
			panic("failed to translate address")
		})
		c.ContactPoints = clusterHosts
	}

	testCases := []struct {
		name        string
		clusterMods []func(*Config)
	}{
		{
			name:        "OneDNSPerNode",
			clusterMods: []func(*Config){OneDNSPerNode},
		},
		{
			name:        "OneDNSPerCluster",
			clusterMods: []func(*Config){OneDNSPerCluster},
		},
		{
			name:        "AddressTranslator+OneDNSPerNode",
			clusterMods: []func(*Config){WithAddressTranslator, OneDNSPerNode},
		},
		{
			name:        "AddressTranslator+OneDNSPerCluster",
			clusterMods: []func(*Config){WithAddressTranslator, OneDNSPerCluster},
		},
		{
			name:        "OneDNSPerClusterFirstBroken",
			clusterMods: []func(*Config){OneDNSPerClusterFirstBroken},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			cluster := createV2Cluster(tc.clusterMods...)
			checkIfSessionWorking(t, cluster, getClusterHosts())
		})
	}
}

func TestErrorsParse(t *testing.T) {
	t.Parallel()

	session := createV2Session(t)
	defer session.Close()

	table := testTableName(t, session.ID())

	if err := v2CreateTable(context.Background(), session, fmt.Sprintf((`CREATE TABLE `+fixtureKeyspace("")+`.%s (id int primary key)`), table)); err != nil {
		t.Fatal("create:", err)
	}

	if err := v2CreateTable(context.Background(), session, fmt.Sprintf((`CREATE TABLE `+fixtureKeyspace("")+`.%s (id int primary key)`), table)); err == nil {
		t.Fatal("Should have gotten already exists error from cassandra server.")
	} else {
		e := &RequestErrAlreadyExists{}
		if errors.As(err, &e) {
			if e.Table != table {
				t.Fatalf("expected error table to be %q but was %q", table, e.Table)
			}
		} else {
			t.Fatalf("expected to get RequestErrAlreadyExists instead got %T", e)
		}
	}
}

func TestRetryOnTopologyBusy(t *testing.T) {
	t.Parallel()

	busy := errors.New("Error during truncate: exceptions::invalid_request_exception (Another global topology request is ongoing, please retry.)")
	busyTruncate := errors.New("Error during truncate: std::runtime_error (Another TRUNCATE TABLE is ongoing, please retry.)")
	other := errors.New("some other error")

	// noSleep avoids real backoff so these subtests stay fast and deterministic.
	noSleep := func(time.Duration) {}

	t.Run("retries busy then succeeds", func(t *testing.T) {
		calls := 0
		err := retryOnTopologyBusyWithSleep(func() error {
			calls++
			if calls < 3 {
				return busy
			}
			return nil
		}, noSleep)
		if err != nil {
			t.Fatalf("expected success, got %v", err)
		}
		if calls != 3 {
			t.Fatalf("expected 3 calls, got %d", calls)
		}
	})

	t.Run("does not retry non-busy errors", func(t *testing.T) {
		calls := 0
		err := retryOnTopologyBusyWithSleep(func() error {
			calls++
			return other
		}, noSleep)
		if err != other {
			t.Fatalf("expected the original error, got %v", err)
		}
		if calls != 1 {
			t.Fatalf("expected 1 call (no retry), got %d", calls)
		}
	})

	t.Run("gives up after max attempts", func(t *testing.T) {
		calls := 0
		err := retryOnTopologyBusyWithSleep(func() error {
			calls++
			return busy
		}, noSleep)
		if !isTopologyBusyErr(err) {
			t.Fatalf("expected the busy error after exhausting retries, got %v", err)
		}
		if calls != 10 {
			t.Fatalf("expected 10 attempts, got %d", calls)
		}
	})

	t.Run("isTopologyBusyErr classification", func(t *testing.T) {
		if !isTopologyBusyErr(busy) {
			t.Error("busy error should be classified as topology-busy")
		}
		if !isTopologyBusyErr(busyTruncate) {
			t.Error("busyTruncate (runtime_error TRUNCATE variant) should be classified as topology-busy")
		}
		if isTopologyBusyErr(other) {
			t.Error("other error should not be classified as topology-busy")
		}
		if isTopologyBusyErr(nil) {
			t.Error("nil should not be classified as topology-busy")
		}
	})

	t.Run("retries the TRUNCATE-variant busy error", func(t *testing.T) {
		calls := 0
		err := retryOnTopologyBusyWithSleep(func() error {
			calls++
			if calls < 2 {
				return busyTruncate
			}
			return nil
		}, noSleep)
		if err != nil {
			t.Fatalf("expected success, got %v", err)
		}
		if calls != 2 {
			t.Fatalf("expected 2 calls, got %d", calls)
		}
	})
}

func TestSerializationSimpleTypesCassandra(t *testing.T) {
	t.Parallel()
	types := valcases.GetSimple()
	// Preserve every one of the 96 binary fixtures and every language adapter.
	t.Run("Marshal", func(t *testing.T) {
		for _, tc := range types {
			t.Run(tc.CQLName, func(t *testing.T) {
				for _, vc := range tc.Cases {
					for _, lc := range vc.LangCases {
						t.Run(vc.Name+"/"+lc.LangType, func(t *testing.T) {
							typ, err := ScalarType(Type(tc.CQLType))
							if err != nil {
								t.Fatal(err)
							}
							value, err := serializationFixtureValue(Type(tc.CQLType), lc.Value)
							if err != nil {
								t.Fatal(err)
							}
							for _, owned := range []bool{false, true} {
								var encoded EncodedValue
								if owned {
									encoded, err = EncodeValueOwned(typ, DynamicCodec, value)
								} else {
									encoded, err = EncodeValueBorrowed(typ, DynamicCodec, value)
								}
								if (err != nil) != lc.ErrInsert {
									t.Fatalf("encode error: %v (expected error %t)", err, lc.ErrInsert)
								}
								if err != nil {
									continue
								}
								if !bytes.Equal(vc.Data, encoded.Bytes().OwnedBytes()) {
									t.Fatalf("binary fixture: expected %x, got %x", vc.Data, encoded.Bytes().OwnedBytes())
								}
								if (vc.Data == nil) != (encoded.State() == Null) {
									t.Fatalf("null/present distinction lost: %s", vc.Name)
								}
							}
						})
					}
				}
			})
		}
	})
	t.Run("Unmarshal", func(t *testing.T) {
		for _, tc := range types {
			t.Run(tc.CQLName, func(t *testing.T) {
				for _, vc := range tc.Cases {
					for _, lc := range vc.LangCases {
						t.Run(vc.Name+"/"+lc.LangType, func(t *testing.T) {
							typ, err := ScalarType(Type(tc.CQLType))
							if err != nil {
								t.Fatal(err)
							}
							state := Present
							if vc.Data == nil {
								state = Null
							}
							encoded, err := NewEncodedValue(typ, state, BorrowBytes(vc.Data))
							if err != nil {
								t.Fatal(err)
							}
							actual, err := DecodeValue(DynamicCodec, encoded)
							if (err != nil) != lc.ErrSelect {
								t.Fatalf("decode error: %v (expected error %t)", err, lc.ErrSelect)
							}
							if err != nil {
								return
							}
							expected, err := serializationFixtureValue(Type(tc.CQLType), lc.Value)
							if err != nil {
								t.Fatal(err)
							}
							assertSerializationValue(t, expected, actual)
						})
					}
				}
			})
		}
	})
	s := createV2Session(t)
	defer s.Close()
	tables := make([]string, len(types))
	for i, tc := range types {
		tables[i] = serializationTableName(t, tc.CQLName)
		serializationDDL(t, s, fmt.Sprintf("CREATE TABLE %s(test_id text PRIMARY KEY,test_col %s)", tables[i], tc.CQLName))
	}
	t.Run("InsertSelect", func(t *testing.T) {
		for i, tc := range types {
			t.Run(tc.CQLName, func(t *testing.T) {
				for _, vc := range tc.Cases {
					for _, lc := range vc.LangCases {
						t.Run(vc.Name+"/"+lc.LangType, func(t *testing.T) {
							input, err := serializationFixtureValue(Type(tc.CQLType), lc.Value)
							if err != nil {
								t.Fatal(err)
							}
							id := vc.Name + "/" + lc.LangType
							_, err = v2Exec(t.Context(), s, fmt.Sprintf("INSERT INTO %s(test_id,test_col) VALUES(?,?)", tables[i]), codecTestMust(TextValue(id)), input)
							if (err != nil) != lc.ErrInsert {
								t.Fatalf("insert error: %v (expected error %t)", err, lc.ErrInsert)
							}
							if err != nil {
								return
							}
							cql := fmt.Sprintf("SELECT test_col FROM %s WHERE test_id=?", tables[i])
							got := serializationColumn(t, s, cql, codecTestMust(TextValue(id)))
							assertSerializationValue(t, input, got)
							raw, err := serializationOne(s, cql, OneColumn(serializationRawDecoder{}), codecTestMust(TextValue(id)))
							if err != nil {
								t.Fatal(err)
							}
							if !bytes.Equal(vc.Data, raw.Bytes().OwnedBytes()) {
								t.Fatalf("database binary fixture: expected %x, got %x", vc.Data, raw.Bytes().OwnedBytes())
							}
							if (vc.Data == nil) != (raw.State() == Null) {
								t.Fatal("database null/present distinction lost")
							}
						})
					}
				}
			})
		}
	})
}

