func TestNewConnectWithLowTimeout(t *testing.T) {
	t.Parallel()

	// Point of these tests to make sure that with low timeout connection creation will gracefully fail

	type TestExpectation int
	const (
		DontRun TestExpectation = iota
		Fail    TestExpectation = iota
		Pass    TestExpectation = iota
		CanPass TestExpectation = iota
	)

	match := func(t *testing.T, e TestExpectation, result error) {
		t.Helper()

		switch e {
		case DontRun:
			t.Fatal("should not be run")
		case Fail:
			if result == nil {
				t.Fatal("should return an error")
			}
		case Pass:
			if result != nil {
				t.Fatalf("should pass, but returned an error: %s", result.Error())
			}
		case CanPass:
			if result == nil {
				t.Log("test passed due to high timeout")
			}
		default:
			panic(fmt.Sprintf("unknown test expectation: %v", e))
		}
	}

	for _, lowTimeout := range []time.Duration{1 * time.Nanosecond, 10 * time.Nanosecond, 100 * time.Nanosecond} {
		canPassOnHighTimeout := Fail
		if lowTimeout >= 100*time.Nanosecond {
			canPassOnHighTimeout = CanPass
		}
		t.Run(lowTimeout.String(), func(t *testing.T) {
			for _, tcase := range []struct {
				name                       string
				getCluster                 func() Config
				connect                    TestExpectation
				regularQuery               TestExpectation
				controlQuery               TestExpectation
				controlQueryAfterReconnect TestExpectation
			}{
				{
					name: "Timeout",
					getCluster: func() Config {
						cluster := createV2Cluster()
						profile := cluster.DefaultProfile.Snapshot()
						profile.Timeout = lowTimeout
						if err := cluster.DefaultProfile.Replace(profile); err != nil {
							t.Fatal(err)
						}
						return cluster
					},
					connect: Pass,
					// At 100ns the query can complete before the deadline fires,
					// the same race already tolerated below for WriteTimeout/ReadTimeout.
					regularQuery:               canPassOnHighTimeout,
					controlQuery:               Pass,
					controlQueryAfterReconnect: Pass,
				},
				{
					name: "MetadataSchemaRequestTimeout",
					getCluster: func() Config {
						cluster := createV2Cluster()
						cluster.Metadata.RequestTimeout = lowTimeout
						return cluster
					},
					connect:                    Pass,
					regularQuery:               Pass,
					controlQuery:               CanPass,
					controlQueryAfterReconnect: CanPass,
				},
				{
					name: "WriteTimeout",
					getCluster: func() Config {
						cluster := createV2Cluster()
						cluster.WriteTimeout = lowTimeout
						return cluster
					},
					connect:      Pass,
					regularQuery: canPassOnHighTimeout,
					controlQuery: canPassOnHighTimeout,
					// It breaks control connection, then it can start reconnecting in any moment
					// As result test is not stable
					controlQueryAfterReconnect: canPassOnHighTimeout,
				},
				{
					name: "ReadTimeout",
					getCluster: func() Config {
						cluster := createV2Cluster()
						cluster.ReadTimeout = lowTimeout
						return cluster
					},
					connect: Pass,
					// When data is available immediately reading from socket is not failing,
					// despite that deadline is in the past
					// Because of that even with low read timeout it can pass
					regularQuery: CanPass,
					controlQuery: CanPass,
					// It breaks control connection, then it can start reconnecting in any moment
					// As result test is not stable
					controlQueryAfterReconnect: CanPass,
				},
				{
					name: "AllTimeouts",
					getCluster: func() Config {
						cluster := createV2Cluster()
						profile := cluster.DefaultProfile.Snapshot()
						profile.Timeout = lowTimeout
						if err := cluster.DefaultProfile.Replace(profile); err != nil {
							t.Fatal(err)
						}
						cluster.ReadTimeout = lowTimeout
						cluster.WriteTimeout = lowTimeout
						cluster.Metadata.RequestTimeout = lowTimeout
						return cluster
					},
					connect:                    Pass,
					regularQuery:               Fail,
					controlQuery:               Fail,
					controlQueryAfterReconnect: Fail,
				},
			} {
				t.Run(tcase.name, func(t *testing.T) {
					var (
						s   *Session
						err error
					)

					t.Run("Connect", func(t *testing.T) {
						s, err = Connect(context.Background(), tcase.getCluster())
						match(t, tcase.connect, err)
						if err != nil {
							t.Fatal("failed to create session", err.Error())
						}
					})
					if s != nil {
						defer s.Close()
					} else {
						if tcase.connect == Fail {
							t.FailNow()
						} else {
							t.Fatal("session was not created")
						}
					}

					if tcase.regularQuery != DontRun {
						t.Run("Regular Query", func(t *testing.T) {
							_, err = v2ReadOne(context.Background(), s, "SELECT key FROM system.local WHERE key='local'")
							match(t, tcase.regularQuery, err)
						})
					}

					if tcase.controlQuery != DontRun {
						t.Run("Query from control connection", func(t *testing.T) {
							err = queryV2ControlKey(context.Background(), s)
							match(t, tcase.controlQuery, err)
						})
					}

					if tcase.controlQueryAfterReconnect != DontRun {
						t.Run("Query from control connection after reconnect", func(t *testing.T) {
							s, err = Connect(context.Background(), tcase.getCluster())
							if err != nil {
								t.Fatal("failed to create session", err.Error())
							}
							defer s.Close()
							err = s.control.reconnect()
							if err != nil {
								t.Fatalf("failed to reconnect to control connection: %v", err)
							}
							err = queryV2ControlKey(context.Background(), s)
							match(t, tcase.controlQueryAfterReconnect, err)
						})
					}
				})
			}
		})
	}
}

func TestCCM(t *testing.T) {
	if err := AllUp(); err != nil {
		t.Fatal(err)
	}

	status, err := Status()
	if err != nil {
		t.Fatal(err)
	}

	if host, ok := status["node1"]; !ok {
		t.Fatal("node1 not in status list")
	} else if !host.State.IsUp() {
		t.Fatal("node1 is not up")
	}

	NodeDown("node1")
	status, err = Status()
	if err != nil {
		t.Fatal(err)
	}

	if host, ok := status["node1"]; !ok {
		t.Fatal("node1 not in status list")
	} else if host.State.IsUp() {
		t.Fatal("node1 is not down")
	}

	NodeUp("node1")
	status, err = Status()
	if err != nil {
		t.Fatal(err)
	}

	if host, ok := status["node1"]; !ok {
		t.Fatal("node1 not in status list")
	} else if !host.State.IsUp() {
		t.Fatal("node1 is not up")
	}
}

func TestKeyspaceTable(t *testing.T) {
	t.Parallel()
	ctx := context.Background()
	cluster := createV2Cluster()
	v2ConfigureRouting(t, &cluster, RoutingOptions{TokenAware: true})
	session, err := Connect(ctx, cluster)
	if err != nil {
		t.Fatal("connect:", err)
	}
	defer session.Close()
	cluster.Keyspace = "wrong_keyspace"
	keyspace, table := v2SchemaRoutingName(t), v2SchemaRoutingName(t)
	v2CreateRoutingKeyspace(t, session, keyspace, 1)
	defer cleanup(t, session, keyspace)
	if err := v2CreateTable(ctx, session, fmt.Sprintf(`CREATE TABLE %s.%s (pk int, ck int, v int, PRIMARY KEY (pk, ck))`, keyspace, table)); err != nil {
		t.Fatal(err)
	}
	if _, err := v2SchemaRoutingExec(ctx, session, fmt.Sprintf(`INSERT INTO %s.%s(pk, ck, v) VALUES (?, ?, ?)`, keyspace, table), Options{Consistency: Option[Consistency]{Value: One, Set: true}}, IntValue(1), IntValue(2), IntValue(3)); err != nil {
		t.Fatal(err)
	}
	prepared, err := Prepare(ctx, session, Statement[[]Value, DynamicRow]{CQL: fmt.Sprintf(`SELECT pk FROM %s.%s WHERE pk = ? LIMIT 1`, keyspace, table), Params: DynamicParams, Rows: DynamicRows}, PrepareOptions{})
	if err != nil {
		t.Fatal(err)
	}
	bound, err := BindOwned(prepared, []Value{IntValue(1)})
	if err != nil {
		t.Fatal(err)
	}
	defer bound.Close()
	rows, err := Run(ctx, session, bound, Options{Consistency: Option[Consistency]{Value: One, Set: true}})
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	if !rows.Next() {
		t.Fatalf("missing row: %v", rows.Err())
	}
	row := rows.Row()
	tests.AssertEqual(t, "pk", int32(1), v2SchemaRoutingInt(t, row, "pk"))
	if rows.Next() {
		t.Fatal("unexpected extra row")
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	info := prepared.Info()
	tests.AssertEqual(t, "prepared.Keyspace", keyspace, info.Keyspace)
	tests.AssertEqual(t, "prepared.Table", table, info.Table)
	tests.AssertEqual(t, "bound.Keyspace", keyspace, bound.Routing().Keyspace)
	tests.AssertEqual(t, "bound.Table", table, bound.Routing().Table)
	tests.AssertTrue(t, "partition-key token is available", bound.Routing().Token.Set)
	metadata, ok := session.Metadata().Keyspace(keyspace)
	tests.AssertTrue(t, "keyspace is present", ok)
	tableMetadata := metadata.Tables[table]
	tests.AssertTrue(t, "table is present", tableMetadata != nil)
	tests.AssertEqual(t, "partition key metadata", "pk", tableMetadata.PartitionKey[0].Name)
	tests.AssertEqual(t, "clustering key metadata", "ck", tableMetadata.ClusteringColumns[0].Name)
}

